CREATE TABLE IF NOT EXISTS recipes(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),task_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE',active_version TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recipe_versions(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),recipe_id TEXT NOT NULL REFERENCES recipes(id),version TEXT NOT NULL,definition_json TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(workspace_id,recipe_id,version));
CREATE TABLE IF NOT EXISTS ai_providers(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),provider_id TEXT NOT NULL,state TEXT NOT NULL,capabilities_json TEXT NOT NULL DEFAULT '[]',quota_state TEXT NOT NULL DEFAULT 'UNKNOWN',last_checked_at TEXT,limitations_json TEXT NOT NULL DEFAULT '[]',UNIQUE(workspace_id,provider_id));
CREATE TABLE IF NOT EXISTS provider_capabilities(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),provider_id TEXT NOT NULL,capability TEXT NOT NULL,ready INTEGER NOT NULL DEFAULT 0,evidence_ref TEXT,checked_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_requests(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),recipe_id TEXT NOT NULL,task_type TEXT NOT NULL,data_class TEXT NOT NULL,preferred_mode TEXT NOT NULL,input_hash TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_responses(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES ai_requests(id),provider_id TEXT NOT NULL,model_id TEXT,status TEXT NOT NULL,output_json TEXT,raw_output_ref TEXT,input_hash TEXT NOT NULL,output_hash TEXT,latency_ms INTEGER,limitations_json TEXT NOT NULL DEFAULT '[]',received_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_evaluations(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),request_id TEXT NOT NULL REFERENCES ai_requests(id),evaluator_type TEXT NOT NULL,result_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_rules(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL,rule_json TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research_items(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),topic TEXT NOT NULL,source_url TEXT NOT NULL,source_title TEXT NOT NULL,source_type TEXT NOT NULL,published_at TEXT,captured_at TEXT NOT NULL,summary TEXT NOT NULL,observations TEXT NOT NULL,implications TEXT NOT NULL,content_opportunities TEXT NOT NULL,campaign_opportunities TEXT NOT NULL,confidence TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS keywords(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),keyword TEXT NOT NULL,source TEXT NOT NULL,intent TEXT,topic TEXT,volume_if_available REAL,difficulty_if_available REAL,priority TEXT,content_opportunity TEXT,pinterest_opportunity TEXT,blog_opportunity TEXT,status TEXT NOT NULL);
